window.RTLBenchLSData.register("assets/d3ff4928b0f8ca564f46ae17103e9bca52e6cb2357e2418c6f92cf3a536e66c3.txt","module origen_134616(\n    input [3:0] A0, A1, A2, A3,\n    input S0, S1,\n    output X\n);\n\n    wire [3:0] mux1_out, mux2_out;\n    wire buf_out;\n\n    // First stage: Two 4-to-2 multiplexers\n    mux4to2 mux1 (\n        .A0(A0),\n        .A1(A1),\n        .A2(A2),\n        .A3(A3),\n        .S0(S0),\n        .S1(S1),\n        .X(mux1_out)\n    );\n\n    mux4to2 mux2 (\n        .A0(A0),\n        .A1(A1),\n        .A2(A2),\n        .A3(A3),\n        .S0(S0),\n        .S1(S1),\n        .X(mux2_out)\n    );\n\n    // Second stage: Buffer\n    buf_gate buffer (\n        .A(mux1_out[0]),\n        .Y(buf_out)\n    );\n\n    // Final output selection\n    assign X = (S1) ? mux2_out[0] : buf_out;\n\nendmodule\n\n// 4-to-2 Multiplexer\nmodule mux4to2(\n    input [3:0] A0, A1, A2, A3,\n    input S0, S1,\n    output [3:0] X\n);\n    assign X = S1 ? (S0 ? A3 : A2) : (S0 ? A1 : A0);\nendmodule\n\n// Buffer\nmodule buf_gate(\n    input A,\n    output Y\n);\n    assign Y = A;\nendmodule");
